<template><div ref="viewport" class="canvas-viewport" :class="{preview:previewMode}" @pointerdown.self="$emit('select','')"><div class="canvas-scaler" :style="{width:`${overlay.resolution.width*scale}px`,height:`${overlay.resolution.height*scale}px`}"><div ref="canvas" class="overlay-canvas" :style="canvasStyle"><div v-if="!previewMode" class="canvas-grid"></div><template v-if="!previewMode&&showGuides"><div class="safe-guide webcam">Webcam safe area</div><div class="safe-guide chat">Chat safe area</div><div class="safe-guide alerts">Alert safe area</div><div class="safe-guide action">HUD / action safe area</div></template><div v-for="guide in snapGuides" :key="`${guide.axis}-${guide.value}`" class="snap-guide" :class="guide.axis" :style="guideStyle(guide)"></div><div v-for="widget in orderedWidgets" v-show="widget.enabled" :key="widget.id" class="widget-frame" :class="{selected:widget.id===selectedId,locked:widget.locked}" :style="frameStyle(widget)" :tabindex="previewMode?-1:0" :aria-label="`${widget.name}${widget.locked?', locked':''}`" @pointerdown.stop="startMove($event,widget)" @click.stop="$emit('select',widget.id)" @keydown="nudge($event,widget)"><component :is="registry[widget.type].component" :widget="widget"/><template v-if="!previewMode&&widget.id===selectedId&&!widget.locked"><button v-for="handle in handles" :key="handle" type="button" class="resize-handle" :class="handle" :aria-label="`Resize ${widget.name} from ${handle}`" @pointerdown.stop="startResize($event,widget,handle)"></button></template><span v-if="!previewMode&&widget.locked" class="lock-badge">Locked</span></div></div></div></div>
</template>
<script setup>import { computed,nextTick,onBeforeUnmount,onMounted,ref } from 'vue'; import { widgetRegistry as registry } from '../../overlays/widgetRegistry.js'; import { clientDeltaToCanvas,editorScale,moveFrame,resizeFrame } from '../../overlays/overlayGeometry.js'; const props=defineProps({overlay:{type:Object,required:true},selectedId:String,previewMode:Boolean,showGuides:Boolean}); const emit=defineEmits(['select','change']); const viewport=ref(null); const scale=ref(.45); const snapGuides=ref([]); const handles=['nw','ne','sw','se']; let observer; let interaction=null; const orderedWidgets=computed(()=>[...props.overlay.widgets].sort((a,b)=>a.zIndex-b.zIndex)); function updateScale(){const box=viewport.value?.getBoundingClientRect();if(box)scale.value=editorScale(props.overlay.resolution.width,props.overlay.resolution.height,Math.max(300,box.width-40),Math.max(240,box.height-40))} onMounted(async()=>{await nextTick();updateScale();observer=new ResizeObserver(updateScale);observer.observe(viewport.value)}); onBeforeUnmount(()=>{observer?.disconnect();removeListeners()}); const bg=computed(()=>{const p=props.overlay.preview;if(props.previewMode)return 'transparent';if(p.backgroundType==='solid')return p.color;if(p.backgroundType==='custom'&&p.customImageUrl)return `url(${p.customImageUrl}) center/cover`;if(p.backgroundType==='reference')return p.referenceAssetId==='battle'?'linear-gradient(135deg,#25405b,#111827 55%,#48254f)':p.referenceAssetId==='studio'?'radial-gradient(circle at 50% 30%,#354c68,#111827 65%)':'linear-gradient(145deg,#314d44,#151a26 45%,#32264d)';return 'transparent'}); const canvasStyle=computed(()=>({width:`${props.overlay.resolution.width}px`,height:`${props.overlay.resolution.height}px`,transform:`scale(${scale.value})`,transformOrigin:'top left',background:bg.value})); function frameStyle(w){return{left:`${w.frame.x}px`,top:`${w.frame.y}px`,width:`${w.frame.width}px`,height:`${w.frame.height}px`,zIndex:w.zIndex}} function guideStyle(g){return g.axis==='x'?{left:`${g.value}px`}:{top:`${g.value}px`}} function startMove(e,w){emit('select',w.id);if(props.previewMode||w.locked)return;interaction={kind:'move',pointerId:e.pointerId,startX:e.clientX,startY:e.clientY,widget:structuredClone(w)};e.currentTarget.setPointerCapture?.(e.pointerId);addListeners()} function startResize(e,w,handle){interaction={kind:'resize',handle,pointerId:e.pointerId,startX:e.clientX,startY:e.clientY,widget:structuredClone(w)};e.currentTarget.setPointerCapture?.(e.pointerId);addListeners()} function addListeners(){window.addEventListener('pointermove',onMove);window.addEventListener('pointerup',end)} function removeListeners(){window.removeEventListener('pointermove',onMove);window.removeEventListener('pointerup',end)} function onMove(e){if(!interaction)return;const delta=clientDeltaToCanvas(e.clientX-interaction.startX,e.clientY-interaction.startY,scale.value);let frame;if(interaction.kind==='move'){const others=props.overlay.widgets.filter(w=>w.id!==interaction.widget.id).map(w=>w.frame);const moved=moveFrame(interaction.widget.frame,delta,props.overlay.resolution,others);frame=moved.frame;snapGuides.value=moved.guides}else frame=resizeFrame(interaction.widget.frame,interaction.handle,delta,props.overlay.resolution);emit('change',{...interaction.widget,frame},false)} function end(){if(interaction){const current=props.overlay.widgets.find(w=>w.id===interaction.widget.id);if(current)emit('change',structuredClone(current),true)}interaction=null;snapGuides.value=[];removeListeners()} function nudge(e,w){if(props.previewMode||w.locked||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const amount=e.shiftKey?10:1;const delta={x:e.key==='ArrowLeft'?-amount:e.key==='ArrowRight'?amount:0,y:e.key==='ArrowUp'?-amount:e.key==='ArrowDown'?amount:0};emit('change',{...w,frame:moveFrame(w.frame,delta,props.overlay.resolution,[],false).frame},true)}</script>
